from collections import deque
def half_flood(grid,sr,sc,color,d):
 g=[r[:] for r in grid];h=len(g);w=len(g[0]);bg=g[0][0];q=deque([(sr,sc)]);seen={(sr,sc)}
 while q:
  r,c=q.popleft()
  for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
   rr,cc=r+dr,c+dc
   if not(0<=rr<h and 0<=cc<w) or (rr,cc) in seen or g[rr][cc]!=bg:continue
   if d=='up' and rr>sr:continue
   if d=='down' and rr<sr:continue
   if d=='left' and cc>sc:continue
   if d=='right' and cc<sc:continue
   seen.add((rr,cc));g[rr][cc]=color;q.append((rr,cc))
 return g
